function editProject(pid){const p=project(pid);modal(`<h2>Editar proyecto</h2><label>Nombre</label><input id="eName" value="${safe(p.name)}"><label>Descripción</label><textarea id="eDesc">${safe(p.description)}</textarea><div class="actions"><button class="btn" onclick="updateProject('${pid}')">Guardar</button><button class="btn ghost" onclick="closeModal()">Cancelar</button></div>`)}
function updateProject(pid){const p=project(pid);p.name=document.getElementById('eName').value.trim()||p.name;p.description=document.getElementById('eDesc').value;save();closeModal();openProject(pid)}
let selectedMissionIds=new Set();
