function editCoreIdea(k,id){const i=(data.ideasByCore[k]||[]).find(x=>x.id===id)||(data.notes||[]).find(x=>x.id===id);if(!i)return;modal(`<h2>Editar idea</h2><label>Título</label><input id="v37EditIdeaTitle" value="${safe(i.title||'')}"><label>Idea</label><textarea id="v37EditIdeaText">${safe(i.text)}</textarea><div class="actions"><button class="btn" onclick="saveCoreIdeaEdit('${k}','${id}')">Guardar</button><button class="btn danger" onclick="deleteIdeaCompletely('${id}')">Eliminar idea completamente</button><button class="btn ghost" onclick="closeModal()">Cerrar</button></div>`)}
function saveCoreIdeaEdit(k,id){const i=(data.ideasByCore[k]||[]).find(x=>x.id===id)||(data.notes||[]).find(x=>x.id===id);if(!i)return;i.title=document.getElementById('v37EditIdeaTitle').value.trim();i.text=document.getElementById('v37EditIdeaText').value.trim();if(!save())return;closeModal();showCore(k)}
function removeIdeaFromGeneral(id,source,core){const i=source==='core'?(data.ideasByCore[core]||[]).find(x=>x.id===id):(data.notes||[]).find(x=>x.id===id);if(!i)return;if(!i.core&&!core)return alert('Esta idea no está asignada a un núcleo. Podés eliminarla desde Editar.');if(!confirm('¿Quitar de Ideas generales y conservar dentro del núcleo?'))return;i.hiddenFromGeneral=true;if(!save())return;render()}
function deleteIdeaCompletely(id){if(!confirm('¿Eliminar esta idea definitivamente, también del núcleo?'))return;data.notes=(data.notes||[]).filter(x=>x.id!==id);Object.keys(data.ideasByCore||{}).forEach(k=>data.ideasByCore[k]=(data.ideasByCore[k]||[]).filter(x=>x.id!==id));if(!save())return;closeModal();render()}
let v37PriorityCore='';
function v37PriorityItems(){return [...data.tasks.filter(t=>!t.done&&t.priority==='Alta').map(item=>({kind:'task',item})),...data.missions.filter(m=>!(m.completedAt||m.done)&&!m.archivedCompleted&&m.priority==='Alta').map(item=>({kind:'mission',item}))]}
function v37PrioritySort(a,b){const order=data.priorityOrder||[];const ai=order.indexOf(a.item.id),bi=order.indexOf(b.item.id);if(ai>=0||bi>=0)return (ai<0?999999:ai)-(bi<0?999999:bi);return (a.item.created||0)-(b.item.created||0)}
function v37MovePriority(id,delta){const list=v37PriorityItems().sort(v37PrioritySort),ids=list.map(x=>x.item.id);let i=ids.indexOf(id),j=i+delta;if(i<0||j<0||j>=ids.length)return;[ids[i],ids[j]]=[ids[j],ids[i]];data.priorityOrder=ids;if(!save())return;showAllPriorities()}
function showAllPriorities(){const list=v37PriorityItems().filter(x=>{const p=project(x.item.projectId);return !v37PriorityCore||(p&&p.core===v37PriorityCore)}).sort(v37PrioritySort);const dots=activeCores().map(c=>`<button class="v37-core-dot ${v37PriorityCore===c[0]?'active':''}" style="--v37dot:${data.coreColors?.[c[0]]||defaultCoreColor(c[0])}" onclick="v37PriorityCore='${c[0]}';showAllPriorities()" aria-label="Filtrar por núcleo"></button>`).join('');modal(`<h2>Todas las urgencias</h2><div class="v37-priority-filters"><button class="v37-mini" onclick="v37PriorityCore='';showAllPriorities()">Todas</button>${dots}</div>${list.map(({kind,item})=>{const p=project(item.projectId),m=kind==='mission'?item:(item.missionId?mission(item.missionId):null);return `<div class="item row between"><div><button class="text-button" onclick="closeModal();${m?`openMission('${m.id}')`:`openProject('${item.projectId}')`}">${safe(kind==='mission'?item.name:item.title)}</button><div class="small">${p?safe(p.name):'Proyecto'} · ${kind==='mission'?'Misión':'Tarea'}</div></div><div class="v37-actions"><button class="v37-mini" onclick="v37MovePriority('${item.id}',-1)">↑</button><button class="v37-mini" onclick="v37MovePriority('${item.id}',1)">↓</button></div></div>`}).join('')||'<p class="muted">No hay urgencias pendientes.</p>'}<div class="actions"><button class="btn ghost" onclick="closeModal()">Cerrar</button></div>`)}
function dismissAdvice(code){if(!data.dismissedAdvice.includes(code))data.dismissedAdvice.push(code);if(!save())return;closeModal();render()}
const v37AttentionProjectCard=attentionProjectCard;
attentionProjectCard=function(){if(data.dismissedAdvice.includes('focus-projects'))return '';const n=attentionProjectNudge();if(!n)return '';return `<section class="attention-section attention-advice"><div class="attention-tag">Sugerencia de enfoque</div><h3>Hey, perrito 🐶</h3><p>El que mucho abarca, poco aprieta. Tenés <b>${n.count} proyectos activos</b>. Antes de sumar más, estaría bueno dedicarles tiempo a los que ya empezaste. Desarrollalos y llevalos adelante.</p><p class="small muted">Podés crear otro proyecto igualmente; HOY solo te invita a enfocarte.</p><div class="attention-actions"><button class="btn secondary" onclick="closeModal();tab='cores';render()">Ver mis proyectos</button><button class="btn ghost" onclick="dismissAdvice('focus-projects')">Eliminar aviso</button></div></section>`};
