function v38PriorityList(){
 const list=[
  ...data.tasks.filter(t=>!t.done&&t.priority==='Alta').map(t=>({kind:'task',item:t})),
  ...data.missions.filter(m=>!(m.completedAt||m.done)&&!m.archivedCompleted&&m.priority==='Alta').map(m=>({kind:'mission',item:m}))
 ];
 const core=data.priorityCoreFilter||'';
 return list.filter(x=>{if(!core)return true;const p=project(x.item.projectId);return p&&p.core===core})
  .sort((a,b)=>(a.item.created||0)-(b.item.created||0));
}
