 const current=data.pinnedShortcuts.map(x=>({...x,item:x.type==='project'?project(x.id):mission(x.id)})).filter(x=>x.item);
 const coresHtml=activeCores().map(c=>`<option value="${c[0]}">${safe(coreName(c[0]))}</option>`).join('');
